function isLocalKiller()
  if localPlayer.Team then
    local c = localPlayer.Team.Name:lower()
    if c:find("killer") or c:find("slasher") or c:find("monster") then
      return true
    end
    if c:find("survivor") then
      return false
    end
  end
  local d = localPlayer:GetAttribute("Role")
  if d == "Killer" or localPlayer:GetAttribute("IsKiller") == true or localPlayer:GetAttribute("Killer") == true then
    return true
  end
  if d == "Survivor" then
    return false
  end
  local f = localPlayer.Character
  if f then
    local d = f:GetAttribute("Role")
    if d == "Killer" or f:GetAttribute("IsKiller") == true or f:GetAttribute("Killer") == true then
      return true
    end
    if d == "Survivor" then
      return false
    end
    local g = f.Parent
    if g and ((g.Name == "Killers" or (g.Name:lower()):find("killer"))) then
      return true
    end
    if g and ((g.Name == "Survivors" or (g.Name:lower()):find("survivor"))) then
      return false
    end
    local h = CollectionService or game:GetService("CollectionService")
    if h and h:HasTag(f, "Killer") then
      return true
    end
    if h and h:HasTag(f, "Survivor") then
      return false
    end
    if f:FindFirstChild("Firstperson") or f:FindFirstChild("KillerActionController") or f:FindFirstChild("Lookscriptkiller") or f:FindFirstChild("VMscript") or f:FindFirstChild("StunEvent") or f:FindFirstChild("Mori") or f:FindFirstChild("MoriEvent") or f:FindFirstChild("Killerost") then
      return true
    end
    if f:FindFirstChild("Machete") or f:FindFirstChild("Knife") or f:FindFirstChild("Weapon") or f:FindFirstChild("Sword") or f:FindFirstChild("Spear") or f:FindFirstChild("Hammer") or f:FindFirstChild("Axe") or f:FindFirstChild("Chainsaw") or f:FindFirstChild("Bat") or f:FindFirstChild("Attack") or f:FindFirstChild("AttackEvent") then
      return true
    end
    local i = f.Name:lower()
    if i:find("veil") or i:find("myers") or i:find("stalker") or i:find("killer") or i:find("abyss") or i:find("slasher") or i:find("masked") or i:find("jason") or i:find("trapper") or i:find("butcher") or i:find("hunter") or i:find("clown") or i:find("doctor") or i:find("phantom") or i:find("hidden") or i:find("nightmarer") then
      return true
    end
  end
  return false
end
