function toBase36(d)
  d = tonumber(d) or 0
  if d == 0 then
    return "0"
  end
  local f = "0123456789abcdefghijklmnopqrstuvwxyz"
  local g = ""
  while d > 0 do
    local c = d % 36
    g = f:sub(c + 1, c + 1) .. g
    d = math.floor(d / 36)
  end
  return g
end
function fromBase36(c)
  if not c or c == "" then
    return "0"
  end
  local d = "0123456789abcdefghijklmnopqrstuvwxyz"
  local f = 0
  for a = 1, #c, 1 do
    local b = c:sub(a, a)
    local e = d:find(b) or 1
    f = f * 36 + ((e - 1))
  end
  return tostring(f)
end
