function updateSCPCache()
  local c = {}
  local d = {}
  local function f(f)
    if f and not d[f] then
      d[f] = true
      table.insert(c, f)
    end
  end
  local g = workspace:FindFirstChild("Map")
  if g then
    for c, d in ipairs({"1"; "2"}) do
      local e = g:FindFirstChild(d)
      if e then
        for c, d in ipairs(e:GetChildren()) do
          if d:IsA("Model") then
