          end
        end
      end
    end
    local function c(c)
      return string.match(c:lower(), "^scp%d*$") ~= nil
    end
    for d, g in ipairs(g:GetChildren()) do
      if g.Name ~= "1" and g.Name ~= "2" then
        if g:IsA("Model") and c(g.Name) then
          f(g)
        elseif g:IsA("Folder") or g:IsA("Model") then
          for d, g in ipairs(g:GetChildren()) do
            if g:IsA("Model") and c(g.Name) then
              f(g)
            end
          end
        end
      end
    end
    for c, d in ipairs(g:GetChildren()) do
      if d:IsA("Model") and d ~= localPlayer.Character then
