  end)
  if d and (f and f ~= "") then
    if f:upper() == "NOSTROMO" then
      return "Loading..."
    end
    return f
  end
  local g = workspace:FindFirstChild("Map")
  if not g then
    Mb = nil
    Nb = "Unknown Map"
    return Nb
  end
  local h = g:FindFirstChildOfClass("Model") or g:FindFirstChildOfClass("Folder") or g
  if h == Mb and Nb ~= "Unknown Map" then
    return Nb
  end
  Mb = h
  if g:FindFirstChild("HooksMeat", true) then
    Nb = "BLOODBATH! Club"
    return Nb
  end
  if g:FindFirstChild("Rooftop", true) then
    Nb = "Mercy Hospital Rooftop"
    return Nb
  end
  if g:FindFirstChild("inviswallasylum", true) then
    Nb = "Mount Massive Asylum"
    return Nb
  end
  if g:FindFirstChild("Tesla", true) then
    Nb = "Site 68"
    return Nb
  end
  if g:FindFirstChild("Breakwater", true) then
    Nb = "The Bay Harbor"
    return Nb
  end
  if g:FindFirstChild("RockVar0", true) then
    Nb = "Woodview Cabin"
    return Nb
  end
  local i = g:FindFirstChild("Model", true)
  if i then
    local c = (i:GetPivot()).Position
    if ((c - Vector3.new(-811.4, 212.8, -7774.5))).Magnitude < 100 then
      Nb = "Firelink Shrine"
      return Nb
    end
    if ((c - Vector3.new(1114.67, -16.92, -12.99))).Magnitude < 100 then
      Nb = "Valdelobos Village"
      return Nb
    end
  end
  Nb = "Unknown Map"
  return Nb
end
