    return
  end
  if searchContainer then
    searchContainer.Visible = false
  end
  if searchBox and searchBox.Text ~= "" then
    searchBox.Text = ""
    if clearSearchBtn then
      clearSearchBtn.Visible = false
    end
  end
  for f, g in pairs(tabButtons) do
    local h = g:FindFirstChild("Icon")
    local i = g:FindFirstChild("ActiveIndicator")
    local j = g:FindFirstChildOfClass("UIStroke")
    if f == d then
      (TweenService:Create(g, TweenInfo.new(.18), {["BackgroundColor3"] = Color3.fromRGB(18, 20, 26),
        ["BackgroundTransparency"] = .1})):Play()
      if j then
        (TweenService:Create(j, TweenInfo.new(.18), {["Transparency"] = 0, ["Color"] = Color3.fromRGB(255, 255, 255)})):Play()
      end
      if h then
        (TweenService:Create(h, TweenInfo.new(.18), {["ImageColor3"] = Color3.fromRGB(255, 255, 255),
          ["ImageTransparency"] = 0})):Play()
      end
      if i then
        (TweenService:Create(i, TweenInfo.new(.18), {["BackgroundTransparency"] = 0; ["Size"] = UDim2.new(0, 3, .7, 0)})):Play()
      end
    else
      (TweenService:Create(g, TweenInfo.new(.18), {["BackgroundColor3"] = Color3.fromRGB(15, 16, 21);
        ["BackgroundTransparency"] = 1})):Play()
      if j then
        (TweenService:Create(j, TweenInfo.new(.18), {["Transparency"] = 1})):Play()
      end
      if h then
        (TweenService:Create(h, TweenInfo.new(.18), {["ImageColor3"] = Color3.fromRGB(255, 255, 255);
          ["ImageTransparency"] = .35})):Play()
      end
      if i then
        (TweenService:Create(i, TweenInfo.new(.18), {["BackgroundTransparency"] = 1, ["Size"] = UDim2.new(0, 0, .7, 0)})):Play()
      end
    end
  end
  for f, g in pairs(tabContainers) do
    if f == d then
      g.Visible = true
      g.GroupTransparency = 1;
      (TweenService:Create(g, TweenInfo.new(.2), {["GroupTransparency"] = 0})):Play()
