  local h = d.tabName or g or currentBuildingTabName or "Home"
  local i = d.sectionName or currentBuildingSectionName or "General"
  local j = {["name"] = f; ["rawLabel"] = d.name, ["tabName"] = h; ["sectionName"] = i; ["controlType"] = d.controlType or "Toggle";
    ["container"] = d.container, ["parent"] = d.parent, ["parentGroup"] = d.parentGroup, ["isPremium"] = d.isPremium or E(d.name),
    ["keybindName"] = d.keybindName; ["controlRef"] = d.controlRef, ["callback"] = d.callback, ["description"] = d.description or ""}
