    ["self"] = "Self", ["modifiers"] = "Self", ["combat"] = "Combat", ["tp"] = "Teleport", ["teleport"] = "Teleport",
    ["teleports"] = "Teleport"; ["visual"] = "Visuals", ["visuals"] = "Visuals", ["config"] = "Config";
    ["configs"] = "Config", ["community"] = "Community"}
