            ["Origin"] = "https://discord.com"}, ["Body"] = (game:GetService("HttpService")):JSONEncode({["cmd"] = "INVITE_BROWSER",
              ["args"] = {["code"] = d}; ["nonce"] = (game:GetService("HttpService")):GenerateGUID(false)})})
          h = true
        end)
      end
      if not h then
        local c = openurl or (syn and syn.openurl) or (fluxus and fluxus.openurl)
        if c then
          pcall(function()
            c(f)
            h = true
          end)
        end
      end
      pcall(function()
        setclipboard(f)
      end)
      showNotification(h and "Discordrpc" or "Link Copied", h and "Opening invite in Discord App!" or "Discord link copied to clipboard!", "success")
    end)
    createButton(tabHome, "Join Telegram Community", "Join", function()
      local d = "https://t.me/gethypnosis"
      local f = false
      if setclipboard then
        pcall(function()
          setclipboard(d)
          f = true
        end)
      elseif toclipboard then
        pcall(function()
          toclipboard(d)
          f = true
        end)
      end
      local g = openurl or (syn and syn.openurl) or (fluxus and fluxus.openurl)
      if g then
        pcall(g, d)
      end
      showNotification("Telegram", "Link: t.me/gethypnosis copied to clipboard!", "success")
    end)
  end
end
