  local f = {["OFF"] = "OFF"; ["IDLE"] = "Idle..."; ["REPAIRING"] = "Repairing Generator"; ["RESCUING"] = "Saving Comrade";
    ["OPENINGGATE"] = "Opening Exit Gate", ["FLEEING"] = "Fleeing Killer", ["ESCAPING"] = "Escaping Match";
    ["ESCAPED"] = "ESCAPED", ["HUNTING"] = "Hunting Survivor", ["CARRYING"] = "Carrying Survivor"; ["HANGING"] = "Hanging Survivor";
    ["PAUSED (Knocked/Hooked)"] = "PAUSED (Knocked/Hooked)"; ["PAUSED (Spectating/Lobby)"] = "PAUSED (Spectating/Lobby)";
    ["PAUSED (Killer Team)"] = "PAUSED (Killer Team)"; ["PAUSED (Survivors Team)"] = "PAUSED (Survivors Team)"}
  local g = {["OFF"] = UI.Muted; ["IDLE"] = UI.TextSub, ["REPAIRING"] = UI.AccentCyan; ["RESCUING"] = UI.Warning,
    ["OPENINGGATE"] = UI.AccentGreen, ["FLEEING"] = UI.Danger, ["ESCAPING"] = UI.AccentGreen; ["ESCAPED"] = UI.AccentGreen,
    ["HUNTING"] = UI.Danger; ["CARRYING"] = UI.Warning; ["HANGING"] = UI.AccentCyan, ["PAUSED (Knocked/Hooked)"] = Color3.fromRGB(200, 200, 50);
    ["PAUSED (Spectating/Lobby)"] = UI.Muted; ["PAUSED (Killer Team)"] = UI.Danger, ["PAUSED (Survivors Team)"] = UI.Danger}
  local h = f[d] or tostring(d)
  local i = g[d] or UI.Muted
  if (tostring(d)):find("WAITING") then
    i = UI.AccentCyan
  elseif (tostring(d)):find("PUMPKIN") then
    i = UI.Accent
  end
  if _G.VD_HomeStatusLabel then
    _G.VD_HomeStatusLabel.Text = h
    _G.VD_HomeStatusLabel.TextColor3 = i
  end
  if _G.VD_HomeStatusDot then
    _G.VD_HomeStatusDot.BackgroundColor3 = i
  end
  if _G.VD_FarmStatusLabel then
    _G.VD_FarmStatusLabel.Text = "Status: " .. h
    _G.VD_FarmStatusLabel.TextColor3 = i
  end
end
_G.VD_UpdateFarmStatus = updateFarmStatus
_G.VD_LastFlashlightEffect = "None"
_G.VD_FlashlightOnState = false
_G.VD_LastHookedLight = nil
_G.VD_LightChangedConn = nil
_G.VD_IsChangingEnabled = false
task.spawn(function()
  local d = 0
  local f = 0
  local g = false
  while activeLoop do
    task.wait(.05)
    f = f + 1
    if f >= 2 then
      f = 0
      g = not g
    end
    pcall(function()
      if f % 4 == 0 then
        local d = y.KillerStainColor or Color3.fromRGB(255, 0, 0)
        for c, f in ipairs((game:GetService("Players")):GetPlayers()) do
          local g = f.Character
          local h = g and g:FindFirstChild("Head")
          local i = h and h:FindFirstChild("RedSurfaceLight")
          if i and i:IsA("Light") then
            if i.Color ~= d then
              i.Color = d
            end
          end
        end
      end
      local h = localPlayer.Character
      local i = h and h:FindFirstChild("Flashlight")
      if i then
        local f = i:FindFirstChildOfClass("SpotLight") or i:FindFirstChild("SpotLight", true)
        if f then
          if f ~= _G.VD_LastHookedLight then
            if _G.VD_LightChangedConn then
              pcall(function()
                _G.VD_LightChangedConn:Disconnect()
              end)
            end
            _G.VD_LastHookedLight = f
            _G.VD_FlashlightOnState = f.Enabled
            _G.VD_LightChangedConn = (f:GetPropertyChangedSignal("Enabled")):Connect(function()
              if _G.VD_IsChangingEnabled then
                return
              end
              _G.VD_FlashlightOnState = f.Enabled
            end)
            registerConnection(_G.VD_LightChangedConn)
          end
          local h = y.FlashlightColor or Color3.fromRGB(255, 255, 255)
          if y.FlashlightEffect == "Rainbow" then
            d = ((d + .008)) % 1
            h = Color3.fromHSV(d, 1, 1)
          end
          for d, f in ipairs(i:GetDescendants()) do
            if f:IsA("Light") then
              f.Color = h
              if _G.VD_FlashlightOnState then
                if y.FlashlightEffect == "Ultra Bright" then
                  _G.VD_IsChangingEnabled = true
                  f.Enabled = true
                  _G.VD_IsChangingEnabled = false
                  f.Range = 250
                  f.Brightness = 15
                elseif y.FlashlightEffect == "Strobe" then
                  _G.VD_IsChangingEnabled = true
                  f.Enabled = g
                  _G.VD_IsChangingEnabled = false
                else
                  if _G.VD_LastFlashlightEffect == "Ultra Bright" then
                    f.Range = 51
                    f.Brightness = 1
                  end
                end
              else
                _G.VD_IsChangingEnabled = true
                f.Enabled = false
                _G.VD_IsChangingEnabled = false
                if _G.VD_LastFlashlightEffect == "Ultra Bright" then
                  f.Range = 51
                  f.Brightness = 1
                end
              end
            elseif f:IsA("Beam") then
              f.Color = ColorSequence.new(h)
              if _G.VD_FlashlightOnState then
                if y.FlashlightEffect == "Strobe" then
                  f.Enabled = g
                elseif y.FlashlightEffect == "Ultra Bright" then
                  f.Enabled = true
                end
              else
                f.Enabled = false
              end
            elseif f:IsA("BasePart") then
              local d = f.Name:lower()
              if d:find("beam") or d:find("light") or d:find("cone") or (f.Transparency > 0 and f.Transparency < 1) then
                f.Color = h
                if _G.VD_FlashlightOnState then
                  if y.FlashlightEffect == "Strobe" then
                    f.Transparency = g and .5 or 1
                  elseif y.FlashlightEffect == "Ultra Bright" then
                    f.Transparency = .4
                  end
                else
                  f.Transparency = 1
                end
              end
            end
          end
        end
        _G.VD_LastFlashlightEffect = y.FlashlightEffect
      end
    end)
  end
end)
