function teleportToInstance(d)
  if not localPlayer or not localPlayer.Character or not localPlayer.Character:FindFirstChild("HumanoidRootPart") then
    return
  end
  local f
  if d:IsA("Model") then
    f = d.PrimaryPart or d:FindFirstChildWhichIsA("BasePart")
  elseif d:IsA("BasePart") then
    f = d
  end
  if f then
    if _G.VD_StopAllInteractions then
      pcall(_G.VD_StopAllInteractions)
      task.wait(.15)
    end
    local d = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")
    if d then
      local g = f.Position + Vector3.new(0, 1.5, 0)
      if y.PathfindingTP ~= false and _G.VD_SmartWalkTo then
        _G.VD_AbortPathfinding = true
        task.wait(.03)
        _G.VD_AbortPathfinding = false
        task.spawn(function()
          local c = _G.VD_SmartWalkTo(g, 3.5)
          if not c and (((f.Position - d.Position)).Magnitude > 4 and not _G.VD_AbortPathfinding) then
            safeSegmentedTeleport(d, f.CFrame + Vector3.new(0, 3, 0))
          end
        end)
        showNotification("Teleport", "Pathfinding to map object...", "info")
      else
        safeSegmentedTeleport(d, f.CFrame + Vector3.new(0, 3, 0))
        showNotification("Teleport", "Teleported to object!", "success")
      end
    end
  end
end
