function collectTPEntries()
  local c = {}
  local d = {}
  local function f(f, g)
    if f and (f.Parent and not d[f]) then
      d[f] = true
      table.insert(c, {["instance"] = f; ["label"] = g})
    end
  end
  local g = activeTPFilter or "All"
  if g == "All" or g == "Generator" then
    for c, d in ipairs(cachedGenerators or {}) do
      if not isGeneratorCompleted(d) then
        f(d, "Generator")
      end
    end
    if #c == 0 and ((g == "Generator" or g == "All")) then
      local c = workspace:FindFirstChild("Map")
      local d = c and c:FindFirstChild("Gens")
      if d then
        for c, d in ipairs(d:GetChildren()) do
          if ((d.Name == "Generator" or string.find(d.Name:lower(), "generator"))) and not isGeneratorCompleted(d) then
            f(d, "Generator")
          end
        end
      end
      for c, d in ipairs(workspace:GetDescendants()) do
        if ((d.Name == "Generator" or (d.Name:lower()):find("generator"))) and (d:IsA("Model") and not isGeneratorCompleted(d)) then
          f(d, "Generator")
        end
      end
    end
  end
  if g == "All" or g == "Hook" then
    for c, d in ipairs(cachedHooks or {}) do
      f(d, "Hook")
    end
    if #c == 0 and ((g == "Hook" or g == "All")) then
      for c, d in ipairs(workspace:GetDescendants()) do
        if (d.Name == "Hook" or d.Name == "HookPoint" or (d.Name:lower()):find("hook")) then
          local c = d:IsA("BasePart") and d or d:FindFirstChild("HookPoint") or (d:IsA("Model") and d.PrimaryPart) or d:FindFirstChildWhichIsA("BasePart")
          if c then
            f(c, "Hook")
          end
        end
      end
    end
  end
  if g == "All" or g == "Pallet" then
    for c, d in ipairs(cachedPallets or {}) do
      f(d, "Pallet")
    end
    if #c == 0 and ((g == "Pallet" or g == "All")) then
      for c, d in ipairs(workspace:GetDescendants()) do
        if (d.Name == "Pallet" or (d.Name:lower()):find("pallet")) then
          f(d, "Pallet")
        end
      end
    end
  end
  if g == "All" or g == "Vault" then
    for c, d in ipairs(cachedVaults or {}) do
      f(d, "Vault")
    end
    if #c == 0 and ((g == "Vault" or g == "All")) then
      for c, d in ipairs(workspace:GetDescendants()) do
        if (d.Name == "Vault" or (d.Name:lower()):find("vault") or d.Name == "Window" or (d.Name:lower()):find("window")) then
          f(d, "Vault")
        end
      end
    end
  end
  if g == "All" or g == "Gate" then
    for c, d in ipairs(cachedGates or {}) do
      f(d, "Gate")
    end
    if #c == 0 and ((g == "Gate" or g == "All")) then
      for c, d in ipairs(workspace:GetDescendants()) do
        if (d.Name == "Gate" or (d.Name:lower()):find("gate") or (d.Name:lower()):find("door")) then
          f(d, "Gate")
        end
      end
    end
  end
  if g == "All" or g == "Pumpkin" then
    for c, d in ipairs(cachedPumpkins or {}) do
      f(d, "Pumpkin")
    end
    if #c == 0 and ((g == "Pumpkin" or g == "All")) then
      local c = workspace:FindFirstChild("Map")
      local d = c and c:FindFirstChild("Pumpkins")
      if d then
        for c, d in ipairs(d:GetChildren()) do
          f(d, "Pumpkin")
        end
      end
    end
  end
  for c, d in ipairs(c) do
    d.dist = getDistance(d.instance)
  end
  table.sort(c, function(c, d)
    return c.dist < d.dist
  end)
  return c
end
refreshTPMenu = function()
  if not tpScroll then
    return
  end
  local c = collectTPEntries()
  clearTPRows()
  if #c == 0 then
    if tpEmptyLabel then
      tpEmptyLabel.Visible = true
    end
    return
  end
  if tpEmptyLabel then
    tpEmptyLabel.Visible = false
  end
  for a, b in ipairs(c) do
    createTPRow(b)
  end
end
