function makeDraggable(d, f)
  local g, h, i, j
  local function k(f)
    local g = f.Position - i
    d.Position = UDim2.new(j.X.Scale, j.X.Offset + g.X, j.Y.Scale, j.Y.Offset + g.Y)
  end
  f.InputBegan:Connect(function(f)
    if f.UserInputType == Enum.UserInputType.MouseButton1 or f.UserInputType == Enum.UserInputType.Touch then
      g = true
      i = f.Position
      j = d.Position
      f.Changed:Connect(function()
        if f.UserInputState == Enum.UserInputState.End then
          g = false
        end
      end)
    end
  end)
  f.InputChanged:Connect(function(c)
    if c.UserInputType == Enum.UserInputType.MouseMovement or c.UserInputType == Enum.UserInputType.Touch then
      h = c
    end
  end)
  registerConnection(UserInputService.InputChanged:Connect(function(a)
    if a == h and g then
      k(a)
    end
  end))
end
makeDraggable(mainFrame, titleBar)
function makeResizable(d, f)
  local g = false
  local h = nil
  local i = nil
  local j = nil
  f.InputBegan:Connect(function(f)
    if f.UserInputType == Enum.UserInputType.MouseButton1 or f.UserInputType == Enum.UserInputType.Touch then
      g = true
      h = f.Position
      i = d.Size
      f.Changed:Connect(function()
        if f.UserInputState == Enum.UserInputState.End then
          g = false
        end
      end)
    end
  end)
  f.InputChanged:Connect(function(c)
    if c.UserInputType == Enum.UserInputType.MouseMovement or c.UserInputType == Enum.UserInputType.Touch then
      j = c
    end
  end)
  registerConnection(UserInputService.InputChanged:Connect(function(c)
    if c == j and g then
      local f = c.Position - h
      local g = math.clamp(i.X.Offset + f.X, 420, 1000)
      local j = math.clamp(i.Y.Offset + f.Y, 260, 800)
      d.Size = UDim2.new(0, g, 0, j)
      UI.MainW = g
      UI.MainH = j
    end
  end))
end
