local function Nc(c, d, f)
  if not c or #c == 0 then
    return nil
  end
  f = math.max(f or 150, 1)
  if d == "Furthest" then
    table.sort(c, function(c, d)
      if math.abs(c.dist - d.dist) > .01 then
        return c.dist > d.dist
      end
      return c.health < d.health
    end)
  elseif d == "Injured" then
    table.sort(c, function(c, d)
      if math.abs(c.health - d.health) > .01 then
        return c.health < d.health
      end
      return c.dist < d.dist
    end)
  elseif d == "Healed" then
    table.sort(c, function(c, d)
      if math.abs(c.health - d.health) > .01 then
        return c.health > d.health
      end
      return c.dist < d.dist
    end)
  elseif d == "NearestInjured" then
    table.sort(c, function(c, d)
      local g = c.dist / f
      local h = d.dist / f
      local i = math.max(c.maxHealth or 100, 1)
      local j = math.max(d.maxHealth or 100, 1)
      local k = math.clamp(c.health / i, 0, 1)
      local l = math.clamp(d.health / j, 0, 1)
      local m = .5 * g + .5 * k
      local n = .5 * h + .5 * l
      if math.abs(m - n) > .001 then
        return m < n
      end
      return c.dist < d.dist
    end)
  elseif d == "NearestHealed" then
    table.sort(c, function(c, d)
      local g = c.dist / f
      local h = d.dist / f
      local i = math.max(c.maxHealth or 100, 1)
      local j = math.max(d.maxHealth or 100, 1)
      local k = math.clamp(c.health / i, 0, 1)
      local l = math.clamp(d.health / j, 0, 1)
      local m = .5 * g + .5 * ((1 - k))
      local n = .5 * h + .5 * ((1 - l))
      if math.abs(m - n) > .001 then
        return m < n
      end
      return c.dist < d.dist
    end)
  elseif d == "FurthestInjured" then
    table.sort(c, function(c, d)
      local g = c.dist / f
      local h = d.dist / f
      local i = math.max(c.maxHealth or 100, 1)
      local j = math.max(d.maxHealth or 100, 1)
      local k = math.clamp(c.health / i, 0, 1)
      local l = math.clamp(d.health / j, 0, 1)
      local m = .5 * ((1 - g)) + .5 * k
      local n = .5 * ((1 - h)) + .5 * l
      if math.abs(m - n) > .001 then
        return m < n
      end
      return c.dist > d.dist
    end)
  elseif d == "FurthestHealed" then
    table.sort(c, function(c, d)
      local g = c.dist / f
      local h = d.dist / f
      local i = math.max(c.maxHealth or 100, 1)
      local j = math.max(d.maxHealth or 100, 1)
      local k = math.clamp(c.health / i, 0, 1)
      local l = math.clamp(d.health / j, 0, 1)
      local m = .5 * ((1 - g)) + .5 * ((1 - k))
      local n = .5 * ((1 - h)) + .5 * ((1 - l))
      if math.abs(m - n) > .001 then
        return m < n
      end
      return c.dist > d.dist
    end)
  else
    table.sort(c, function(c, d)
      if math.abs(c.dist - d.dist) > .01 then
        return c.dist < d.dist
      end
      return c.health < d.health
    end)
  end
  return c[1]
end
